-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"90ba7d13-5dd3-5202-b72e-2122c5e0ffdc","inventory_key":"art-audit:z87","name":"De Bewaerschole","city":"Burgh-Haamstede","province":"Zeeland","street_address":"Weststraat 18","postal_code":"4328 AB","country":"NL","website_url":"https://www.bewaerschole.nl/","latitude":null,"longitude":null,"summary":"Ontdek kunst in de voormalige bewaarschool van Burgh-Haamstede. De Bewaerschole presenteert hedendaagse kunstenaars in een intieme ruimte. Tentoonstellingen leggen vaak verbindingen met de omgeving en nodigen uit tot aandachtig kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","landschap"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Weststraat_18%2C_Haamstede.JPG/1280px-Weststraat_18%2C_Haamstede.JPG","caption":"De Bewaerschole — Weststraat 18, Haamstede","credit":"Rosemoon","source_url":"https://commons.wikimedia.org/wiki/File:Weststraat_18,_Haamstede.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"d383cc7e-bc5c-5034-8e3f-26f77cf0dedd","inventory_key":"art-audit:z91","name":"The Grey Space in the Middle","city":"Den Haag","province":"Zuid-Holland","street_address":"Paviljoensgracht 20","postal_code":"2512 BP","country":"NL","website_url":"https://thegreyspace.net","latitude":null,"longitude":null,"summary":"Ontdek kunst tussen tentoonstelling, performance en ontmoeting. The Grey Space in the Middle geeft ruimte aan experimenten die disciplines doorkruisen. Het programma verandert van karakter met de makers die er aan het werk zijn.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","performance","experiment"],"photos":[],"is_art_museum":true},{"id":"76bb2424-a1d1-5a57-a968-4999c4b12032","inventory_key":"art-audit:z92","name":"Stroom Den Haag","city":"Den Haag","province":"Zuid-Holland","street_address":"Hogewal 1-9","postal_code":"2514 HA","country":"NL","website_url":"https://www.stroom.nl","latitude":null,"longitude":null,"summary":"Kijk met andere ogen naar de stad bij Stroom Den Haag. Tentoonstellingen en projecten verbinden beeldende kunst met architectuur en de publieke ruimte. Kunstenaars maken vertrouwde omgevingen opnieuw het onderzoeken waard.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","architectuur","kunsthal"],"photos":[],"is_art_museum":true},{"id":"c4f26e6f-6dc8-54b7-aa78-0d504149b2ef","inventory_key":"art-audit:z96","name":"The Balcony","city":"Den Haag","province":"Zuid-Holland","street_address":"Nieuwe Molstraat 14A2","postal_code":"2512 BK","country":"NL","website_url":"https://thebalconythehague.com/","latitude":null,"longitude":null,"summary":"Ontdek hedendaagse kunst bij The Balcony. Tentoonstellingen, films en publieke programma''s geven verschillende makers een podium. De kleinschalige plek biedt ruimte voor experiment en gesprekken over wat beelden kunnen betekenen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","videokunst","kunsthal"],"photos":[],"is_art_museum":true},{"id":"c55697d5-d5dc-55e4-ab51-2868762e5d85","inventory_key":"art-audit:z100","name":"V2_","city":"Rotterdam","province":"Zuid-Holland","street_address":"Eendrachtsstraat 10","postal_code":"3012 XL","country":"NL","website_url":"https://www.v2.nl/","latitude":null,"longitude":null,"summary":"Ontdek kunst die technologie onderzoekt en uitdaagt. V2_ verbindt kunstenaars met experiment, onderzoek en publieke presentaties. Nieuwe media worden hier niet alleen gebruikt, maar ook kritisch en speels bevraagd.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["mediakunst","digitale kunst","experiment"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/32/V2_Institute_for_the_Unstable_Media_facade.jpg","caption":"V2_ — V2 Institute for the Unstable Media facade","credit":"Ruiguerra","source_url":"https://commons.wikimedia.org/wiki/File:V2_Institute_for_the_Unstable_Media_facade.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"b3bc3658-ee11-5b7a-862a-198b8a60fc0d","inventory_key":"art-audit:z101","name":"VHDG","city":"Leeuwarden","province":"Friesland","street_address":"Ipe Brouwerssteeg 10A","postal_code":"8911 BZ","country":"NL","website_url":"https://www.voorheendegemeente.nl","latitude":null,"longitude":null,"summary":"Ontdek eigenzinnige makers bij VHDG. Tentoonstellingen en projecten verbinden hedendaagse kunst met Leeuwarden en de omgeving. De instelling geeft ruimte aan experiment, ontwikkeling en ontmoetingen met nieuwe perspectieven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","jong talent"],"photos":[],"is_art_museum":true},{"id":"3dc36ebf-d27d-52db-b49d-b026fc5c6f0f","inventory_key":"museum-nl:w139","name":"W139","city":"Amsterdam","province":"Noord-Holland","street_address":"Warmoesstraat 139","postal_code":"1012 JB","country":"NL","website_url":"https://w139.nl/","latitude":52.373751,"longitude":4.895989,"summary":"Ontdek kunst die door kunstenaars zelf wordt ontwikkeld en gepresenteerd. W139 biedt ruimte aan gezamenlijke projecten, installaties en nieuwe ideeën. Iedere tentoonstelling verandert de grote ruimte en nodigt uit tot een andere manier van kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","experiment"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/W139.jpg/1280px-W139.jpg","caption":"W139 — W139","credit":"Piecesofuk","source_url":"https://commons.wikimedia.org/wiki/File:W139.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"6fc74b6d-e4c5-55e3-aa78-1fe66acb26fc","inventory_key":"art-audit:z105","name":"Witte Rook","city":"Breda","province":"Noord-Brabant","street_address":"Liniestraat 111","postal_code":"4816 BG","country":"NL","website_url":"https://www.witterook.nu","latitude":null,"longitude":null,"summary":"Ontdek het denk- en maakproces van kunstenaars bij Witte Rook. Residenties, presentaties en gesprekken geven ruimte aan onderzoek. De onafhankelijke plek verbindt nieuwe artistieke ideeën met publiek en omgeving.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","onderzoek"],"photos":[],"is_art_museum":true},{"id":"dc985ccf-47c2-58bf-8466-518af0400fcb","inventory_key":"art-audit:z106","name":"Zone2Source","city":"Amsterdam","province":"Noord-Holland","street_address":"Amstelpark 4","postal_code":"1083 HZ","country":"NL","website_url":"https://zone2source.net","latitude":null,"longitude":null,"summary":"Ontdek kunst die onze relatie met natuur onderzoekt. Zone2Source presenteert tentoonstellingen en buitenwerken in het Amstelpark. Kunstenaars gebruiken de omgeving als proeftuin voor nieuwe manieren van kijken en samenleven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","ecologie","land art"],"photos":[],"is_art_museum":true},{"id":"4748fef0-e09d-5cf6-a446-39065bc468ce","inventory_key":"museum-nl:het-schoenenkwartier","name":"Schoenenkwartier","city":"Waalwijk","province":"Noord-Brabant","street_address":"Raadhuisplein 1","postal_code":"5141 KG","country":"NL","website_url":"https://schoenenkwartier.nl/","latitude":null,"longitude":null,"summary":"Ontdek de wereld achter de schoen. Iconische ontwerpen, materialen en maakprocessen laten zien hoe stijl en vernieuwing samengaan. Het Schoenenkwartier verbindt museumcollectie en experiment, zodat je met andere ogen naar alledaagse vormgeving kijkt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["design","mode","schoenen"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Langstraat_-_Waalwijk_-_Schoenenkwartier_2022.jpg/1280px-Langstraat_-_Waalwijk_-_Schoenenkwartier_2022.jpg","caption":"Schoenenkwartier — Langstraat - Waalwijk - Schoenenkwartier 2022","credit":"Daan0416","source_url":"https://commons.wikimedia.org/wiki/File:Langstraat_-_Waalwijk_-_Schoenenkwartier_2022.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"99e5e11c-b0fb-5509-9407-dae7aacbf5c9","inventory_key":"wikipedia:Noord-Brabant:museumofyoungart:oosterhout","name":"MOYA – Museum of Young Art","city":"Oosterhout","province":"Noord-Brabant","street_address":"Sint Vincentiusstraat 113","postal_code":"4901 GJ","country":"NL","website_url":"https://www.moya.museum/","latitude":null,"longitude":null,"summary":"Ontdek hedendaagse kunstenaars in een voormalige kerk van Pierre Cuypers. MOYA verbindt tentoonstellingen met invloeden uit mode en design. Nieuwe makers en gevestigde namen krijgen ruimte voor experiment en directe ontmoetingen met hun werk.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","design"],"photos":[],"is_art_museum":true},{"id":"503f926c-885f-5925-b0e6-cc83832404a6","inventory_key":"museum-nl:verwey-museum-haarlem","name":"Verwey Museum Haarlem","city":"Haarlem","province":"Noord-Holland","street_address":"Groot Heiligland 47","postal_code":"2011 EP","country":"NL","website_url":"https://www.verweymuseumhaarlem.nl/","latitude":null,"longitude":null,"summary":"Ontdek de kunst van Kees Verwey en andere Haarlemse makers. Schilderijen en wisselende tentoonstellingen verbinden artistieke levens met de stad. Het museum laat zien hoe geschiedenis en beeldende kunst elkaar steeds opnieuw ontmoeten.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","moderne kunst","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Entree_Museum_Haarlem.jpg/1280px-Entree_Museum_Haarlem.jpg","caption":"Verwey Museum Haarlem — Entree Museum Haarlem","credit":"ElsBrouwer","source_url":"https://commons.wikimedia.org/wiki/File:Entree_Museum_Haarlem.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"d36bbfc7-4d74-5022-851d-92f2cac85526","inventory_key":"museum-nl:grid-grafisch-museum-groningen-tijdelijk-gesloten","name":"GRID Grafisch Museum Groningen","city":"Groningen","province":"Groningen","street_address":"Melkweg 1","postal_code":"9718 EP","country":"NL","website_url":"https://www.gridgroningen.nl/","latitude":null,"longitude":null,"summary":"Ontdek het samenspel van woord en beeld. GRID bewaart de wereld van grafische technieken en vormgeving. De eigen locatie is gesloten; tijdelijke tentoonstellingen op andere plekken houden de verzameling en het maakverhaal zichtbaar.","operating_status":"temporarily_closed","publication_status":"draft","verification_status":"unreviewed","tags":["grafiek","drukwerk","grafisch ontwerp"],"photos":[],"is_art_museum":true},{"id":"210a5e49-0b2b-5af1-9372-62936689ed75","inventory_key":"art-audit:brood","name":"Herman Brood Museum","city":"Zwolle","province":"Overijssel","street_address":"Blijmarkt 21","postal_code":"8011 ND","country":"NL","website_url":"https://hermanbroodmuseum.nl/pages/contact","latitude":null,"longitude":null,"summary":"Ontdek Herman Brood als beeldend kunstenaar. Zijn uitgesproken kleuren en directe schilderstijl geven energie aan de werken. De presentatie verbindt kunst met het leven van een maker die muziek en beeld moeiteloos door elkaar liet lopen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","kunstenaarsmuseum","popart"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Herman_Brood_Museum_%26_Experience_Zwolle.jpg/1280px-Herman_Brood_Museum_%26_Experience_Zwolle.jpg","caption":"Herman Brood Museum — Herman Brood Museum & Experience Zwolle","credit":"Roger Veringmeier","source_url":"https://commons.wikimedia.org/wiki/File:Herman_Brood_Museum_%26_Experience_Zwolle.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"5de1ef76-c89b-5bd3-87ab-57fcaaf6c35a","inventory_key":"art-audit:bommel","name":"Bommel en Tom Poes Museum","city":"Assen","province":"Drenthe","street_address":"Stationsstraat 24","postal_code":"9401 KX","country":"NL","website_url":"https://www.bommelentompoesmuseum.nl/","latitude":null,"longitude":null,"summary":"Stap in de getekende wereld van Marten Toonder. Bommel en Tom Poes laten zien hoe beeld, taal en verbeelding elkaar versterken. Tentoonstellingen belichten de verhalen en het kunstenaarschap achter deze eigenzinnige figuren.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["stripkunst","illustratie","Marten Toonder"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Bommel_en_Tom_Poes_Museum_%282025%29.jpg/1280px-Bommel_en_Tom_Poes_Museum_%282025%29.jpg","caption":"Bommel en Tom Poes Museum — Bommel en Tom Poes Museum (2025)","credit":"Sneeuwvlakte","source_url":"https://commons.wikimedia.org/wiki/File:Bommel_en_Tom_Poes_Museum_(2025).jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"5a2c98fa-0a13-5f8a-b599-ee2cf067aaeb","inventory_key":"art-audit:six","name":"Collectie Six","city":"Amsterdam","province":"Noord-Holland","street_address":"Amstel 218","postal_code":"","country":"NL","website_url":"https://collectiesix.nl/","latitude":null,"longitude":null,"summary":"Ontdek een familiecollectie die door generaties is opgebouwd. Oude meesters, waaronder Rembrandt, maken deel uit van een persoonlijk geheel van kunst en herinneringen. Bezoek is op afspraak: bekijk vooraf de mogelijkheden op de website.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude meesters","schilderkunst","verzamelaars"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/5/5f/Flinck%2C_Govaert_-_Portrait_Margaretha_Tulp_-_Six_Collection.jpg","caption":"Collectie Six — Flinck, Govaert - Portrait Margaretha Tulp - Six Collection","credit":"Govert Flinck","source_url":"https://commons.wikimedia.org/wiki/File:Flinck,_Govaert_-_Portrait_Margaretha_Tulp_-_Six_Collection.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"18568908-3bcc-5832-8fd0-e3c715f945d6","inventory_key":"art-audit:boterhal","name":"De Boterhal","city":"Hoorn","province":"Noord-Holland","street_address":"Kerkplein 39","postal_code":"1621 CZ","country":"NL","website_url":"https://boterhal.com/","latitude":null,"longitude":null,"summary":"Ontdek kunst van leden en gasten van de Hoornse kunstenaarsvereniging. Wisselende tentoonstellingen brengen verschillende media samen in het voormalige Sint Jans Gasthuis. Het historische gebouw geeft de hedendaagse werken een eigen omgeving.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","kunstenaarsvereniging"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/6/6a/Sint_Jans_Gasthuis.jpg","caption":"De Boterhal — Sint Jans Gasthuis","credit":"Dolfy","source_url":"https://commons.wikimedia.org/wiki/File:Sint_Jans_Gasthuis.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"185cb6d0-5f53-5ae7-b674-31a2337ee561","inventory_key":"art-audit:ekwc","name":"Europees Keramisch Werkcentrum","city":"Oisterwijk","province":"Noord-Brabant","street_address":"Almystraat 10","postal_code":"5061 PA","country":"NL","website_url":"https://ekwc.nl/bezoekersinfo/","latitude":null,"longitude":null,"summary":"Kijk waar keramische ideeën worden uitgeprobeerd. Het EKWC ontvangt kunstenaars, ontwerpers en architecten die de grenzen van klei onderzoeken. Tijdens publieksmomenten en rondleidingen ontdek je het werkproces achter nieuwe vormen en materialen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["keramiek","design","experiment"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Werkplaats-CBF2021.jpg/1280px-Werkplaats-CBF2021.jpg","caption":"Europees Keramisch Werkcentrum — Werkplaats-CBF2021","credit":"Charleyatekwc","source_url":"https://commons.wikimedia.org/wiki/File:Werkplaats-CBF2021.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"8fa74ff1-0c85-53cc-8a02-bd1b25b0ef33","inventory_key":"art-audit:havixhorst","name":"Beeldentuin De Havixhorst","city":"De Schiphorst","province":"Drenthe","street_address":"Schiphorsterweg 34-36","postal_code":"7966 AC","country":"NL","website_url":"https://www.beeldentuindehavixhorst.nl/","latitude":null,"longitude":null,"summary":"Wandel door een eeuw Nederlandse beeldhouwkunst. De tuin van De Havixhorst brengt sculpturen uit de twintigste en eenentwintigste eeuw samen. Licht, groen en ruimte laten de vormen bij iedere stap anders uitkomen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["beeldhouwkunst","beeldentuin","moderne kunst"],"photos":[],"is_art_museum":true},{"id":"2ad664ac-fdb1-5a39-a587-feea9ed9608e","inventory_key":"art-audit:twickel","name":"Museum MORE Twickel","city":"Delden","province":"Overijssel","street_address":"Hengelosestraat 2/4","postal_code":"7491 BR","country":"NL","website_url":"https://www.moretwickel.nl/","latitude":null,"longitude":null,"summary":"Ontdek de verstilde schilderkunst van Jan Mankes in de Oude Rentmeesterij. MORE Twickel verbindt figuratieve kunst met de natuur van het landgoed. Wisselende tentoonstellingen voegen nieuwe perspectieven toe aan deze intieme plek.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["realisme","schilderkunst","Jan Mankes"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/1/12/Delden_hengelosestraat_2_4_rentmeesterij.jpg","caption":"Museum MORE Twickel — Delden hengelosestraat 2 4 rentmeesterij","credit":"Notum-sit","source_url":"https://commons.wikimedia.org/wiki/File:Delden_hengelosestraat_2_4_rentmeesterij.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
insert into public.kk_museum_editorial(museum_id,review_notes,suggested_tags)
select museum_id,review_notes,suggested_tags from jsonb_populate_recordset(null::public.kk_museum_editorial,'[{"museum_id":"90ba7d13-5dd3-5202-b72e-2122c5e0ffdc","review_notes":"Kunstinstelling met publiek tentoonstellingsprogramma. Geen vaste collectie verondersteld. Raadpleeg het programma voor bezoek; open geldt als actieve instelling, niet als dagelijkse openstelling.","suggested_tags":[]},{"museum_id":"d383cc7e-bc5c-5034-8e3f-26f77cf0dedd","review_notes":"Kunstinstelling met publiek tentoonstellingsprogramma. Geen vaste collectie verondersteld. Raadpleeg het programma voor bezoek; open geldt als actieve instelling, niet als dagelijkse openstelling. FOTO ONTBREEKT: nog een passende foto met aantoonbaar hergebruikrecht toevoegen.","suggested_tags":[]},{"museum_id":"76bb2424-a1d1-5a57-a968-4999c4b12032","review_notes":"Kunstinstelling met publiek tentoonstellingsprogramma. Geen vaste collectie verondersteld. Raadpleeg het programma voor bezoek; open geldt als actieve instelling, niet als dagelijkse openstelling. FOTO ONTBREEKT: nog een passende foto met aantoonbaar hergebruikrecht toevoegen.","suggested_tags":[]},{"museum_id":"c4f26e6f-6dc8-54b7-aa78-0d504149b2ef","review_notes":"Kunstinstelling met publiek tentoonstellingsprogramma. Geen vaste collectie verondersteld. Raadpleeg het programma voor bezoek; open geldt als actieve instelling, niet als dagelijkse openstelling. FOTO ONTBREEKT: nog een passende foto met aantoonbaar hergebruikrecht toevoegen.","suggested_tags":[]},{"museum_id":"c55697d5-d5dc-55e4-ab51-2868762e5d85","review_notes":"Kunstinstelling met publiek tentoonstellingsprogramma. Geen vaste collectie verondersteld. Raadpleeg het programma voor bezoek; open geldt als actieve instelling, niet als dagelijkse openstelling.","suggested_tags":[]},{"museum_id":"b3bc3658-ee11-5b7a-862a-198b8a60fc0d","review_notes":"Kunstinstelling met publiek tentoonstellingsprogramma. Geen vaste collectie verondersteld. Raadpleeg het programma voor bezoek; open geldt als a